    if (!h.id || !Number.isFinite(requireKnown(h.cores, "cores")) || requireKnown(h.cores, "cores") <= 0 || !Number.isSafeInteger(requireKnown(h.memory, "bytes")) || requireKnown(h.memory, "bytes") < 0) throw Error("Invalid host budget");
